+fn steel_hits(world: &World) -> Vec<usize> {
+    let c = cache(world, "F1").expect("cached");
+    c.warnings.iter().filter_map(|w| match *w {
+        Warning::FixtureHit { at, fixture_part: FixturePart::Holder } => Some(at),
+        _ => None,
+    }).collect()
+}
